    const[users, setUsers] = useState({})
const displayAllUsers = async () => {
    try{
    const userList = await axios.get('/chatUsers/allUsers/')

    setUsers(userList.data)
    }
      catch (err) {
            console.log(err);

        }
}
  useEffect(()=>{
    displayAllUsers()
    console.log(users);

  },[])


  return (
  <li>
{     Array.isArray(users) ? 
    users.map(u => {
          return(<>
          <ul>

            {u.email}<Button>Add Friend</Button>
          </ul>

          </>
          )
    }
) : null
}
  </li>  

  )
}
